package ir.neshane.isolationprobe.recovery;

import static ir.neshane.isolationprobe.recovery.LabRecoveryTrust.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;

/** Owning fixture service. Recovery and workload credentials never cross owners. */
public final class LabRecoveryWorkload {
    private final Path d;
    private final String node;
    private final Set<String> nonces=ConcurrentHashMap.newKeySet();
    private final String boot=UUID.randomUUID().toString();
    LabRecoveryWorkload(Path d,String node)throws Exception{this.d=d;this.node=node;if(node.equals("restored-owner"))for(String cell:List.of("a","b"))try(var c=db(cell);var s=c.createStatement()){s.executeUpdate("UPDATE recovery.gate SET state='QUARANTINED',acknowledged=false");}}
    private String cell(String tenant){require(Set.of("tenant-a","tenant-b").contains(tenant),"UNKNOWN_TENANT");return tenant.substring(7);}
    private Connection db(String cell)throws Exception{return database(d,"db."+cell,Files.readString(d.resolve("db.host")).strip(),"dr_"+cell,"verify-full","");}
    private Map<String,String> current(String tenant)throws Exception{String nonce=UUID.randomUUID().toString();return ReconciliationPolicy.verifySnapshot(d,call(d,"recovery-authority",8443,map("command","snapshot","tenant",tenant,"nonce",nonce)),tenant,nonce);}
    private Map<String,String> data(Connection c)throws Exception{var m=new TreeMap<String,String>();try(var s=c.createStatement();var r=s.executeQuery("SELECT tenant_id,cell_id,deployment_id FROM lab_data.identity")){require(r.next(),"IDENTITY_MISSING");m.put("tenant",r.getString(1));m.put("cell",r.getString(2));m.put("deployment",r.getString(3));require(!r.next(),"IDENTITY_AMBIGUOUS");}try(var s=c.createStatement();var r=s.executeQuery("SELECT version,value FROM lab_data.markers WHERE marker_id='marker'")){require(r.next(),"MARKER_MISSING");m.put("sequence",""+r.getLong(1));m.put("value",r.getString(2));require(!r.next(),"MARKER_AMBIGUOUS");}var ops=new TreeMap<String,String>();try(var s=c.createStatement();var r=s.executeQuery("SELECT operation_id,payload FROM lab_data.operations ORDER BY sequence")){while(r.next())ops.put(r.getString(1),r.getString(2));}m.put("operations",packed(ops));return m;}
    private Map<String,String> gate(Connection c,boolean lock)throws Exception{try(var s=c.createStatement();var r=s.executeQuery("SELECT tenant_id,cell_id,destination_id,incarnation,state,coalesce(attempt_id,''),placement_epoch,credential_epoch,fence_generation,authority_version,acknowledged,coalesce(data_digest,'') FROM recovery.gate"+(lock?" FOR UPDATE":""))){require(r.next(),"GATE_MISSING");return map("tenant",r.getString(1),"cell",r.getString(2),"destination",r.getString(3),"incarnation",r.getString(4),"state",r.getString(5),"attempt",r.getString(6),"placement",""+r.getLong(7),"credential",""+r.getLong(8),"fence",""+r.getLong(9),"revision",""+r.getLong(10),"acknowledged",""+r.getBoolean(11),"data-digest",r.getString(12));}}
    private void audit(Connection c,String tenant,String attempt,String category,String operation,String state,String digest)throws Exception{try(var p=c.prepareStatement("INSERT INTO recovery.audit VALUES (?,?,?,?,?,?,?)")){p.setString(1,UUID.randomUUID().toString());p.setString(2,attempt);p.setString(3,tenant);p.setString(4,category);p.setString(5,operation);p.setString(6,state);p.setString(7,digest);p.executeUpdate();}}
    private void active(Map<String,String> local,Map<String,String> authoritative)throws Exception{require(local.get("state").equals("ACTIVE")&&local.get("acknowledged").equals("true"),"QUARANTINED");for(String f:List.of("tenant","cell","placement","credential","fence"))require(local.get(f).equals(authoritative.get(f)),"STALE_ACTIVE_SCOPE");}
    private synchronized Map<String,String> handle(String peer,Map<String,String> r)throws Exception{
        String cmd=r.get("command"),tenant=r.getOrDefault("tenant","tenant-a"),cell=cell(tenant);boolean admin=r.containsKey("mac");if(admin){require(peer.equals("driver"),"ADMIN_PEER");admin(d,r,nonces);}
        if(cmd.equals("health")&&admin)return map("code","OK","boot",boot);
        if(cmd.equals("snapshot")&&admin)try(var c=db(cell)){var s=data(c);s.put("code","OK");return s;}
        if(cmd.equals("gate")&&(admin||peer.equals("recovery-executor")))try(var c=db(cell)){var g=gate(c,false);g.put("code","OK");return g;}
        if(cmd.equals("runtime-access")&&admin){String mode=r.getOrDefault("mode","read");try(var c=database(d,"runtime."+cell,Files.readString(d.resolve("db.host")).strip(),"dr_"+cell,"verify-full","");var s=c.createStatement()){if(mode.equals("write")){boolean denied=false;try{s.executeUpdate("UPDATE lab_data.markers SET value='UNAUTHORIZED'");}catch(SQLException e){denied="42501".equals(e.getSQLState());}require(denied,"RUNTIME_WRITE_UNEXPECTEDLY_ALLOWED");return map("code","DENIED","reason","SQLSTATE_42501","rows","0");}try(var result=s.executeQuery("SELECT count(*) FROM lab_data.markers")){result.next();return map("code","OK","rows",""+result.getLong(1));}}}
        if(cmd.equals("resume")){require(peer.equals("recovery-executor"),"RECOVERY_EXECUTOR_REQUIRED");var now=current(tenant);try(var c=db(cell)){c.setAutoCommit(false);var g=gate(c,true);require(g.get("state").equals("RECONCILING")&&g.get("attempt").equals(r.get("attempt")),"RESUME_BINDING");for(String f:List.of("tenant","cell","placement","credential","fence","revision"))require(g.get(f).equals(now.get(f)),"RESUME_AUTHORITY_CHANGED");var actual=data(c);String digest=ReconciliationPolicy.digest(actual);require(digest.equals(g.get("data-digest"))&&actual.get("operations").equals(byId(now)),"RESUME_DATA_CHANGED");c.rollback();return map("code","OK","state","RECONCILING","data-digest",digest,"reconstruction-effects","0");}}
        if(cmd.equals("fence")){require(admin||peer.equals("recovery-authority"),"FENCE_AUTHORITY_REQUIRED");try(var c=db(cell);var s=c.createStatement()){s.executeUpdate("UPDATE recovery.gate SET state='QUARANTINED',acknowledged=false");}return map("code","OK","phase","LOCALLY_EFFECTIVE");}
        if(cmd.equals("begin")){require(peer.equals("recovery-executor"),"RECOVERY_EXECUTOR_REQUIRED");var manifest=unpack(r.get("manifest"));verify(d,manifest,r.get("manifest-signature"));var grant=unpack(r.get("grant"));verify(d,grant,r.get("grant-signature"));var now=current(tenant);try(var c=db(cell)){c.setAutoCommit(false);var g=gate(c,true);ReconciliationPolicy.grant(grant,manifest,now,r.get("attempt"),g.get("incarnation"));require(g.get("tenant").equals(manifest.get("tenant"))&&g.get("cell").equals(manifest.get("cell"))&&g.get("destination").equals("restored-owner"),"RESTORE_TARGET_SCOPE");if(g.get("state").equals("ACTIVE")&&g.get("attempt").equals(r.get("attempt"))){c.rollback();return map("code","OK","state","ACTIVE","recorded","true");}require(!g.get("state").equals("ACTIVE")&&(g.get("attempt").isEmpty()||g.get("attempt").equals(r.get("attempt"))),"RECOVERY_ATTEMPT_CONFLICT");var actual=data(c);require(ReconciliationPolicy.digest(actual).equals(manifest.get("data-digest")),"RESTORED_DATA_SUBSTITUTED");for(String field:List.of("tenant","cell","deployment"))require(actual.get(field).equals(manifest.get(field)),"RESTORED_IDENTITY_MISMATCH");try(var p=c.prepareStatement("UPDATE recovery.gate SET state='VALIDATING',attempt_id=?,acknowledged=false")){p.setString(1,r.get("attempt"));p.executeUpdate();}audit(c,tenant,r.get("attempt"),"STATE","","VALIDATING",manifest.get("archive-digest"));c.commit();return map("code","OK","state","VALIDATING");}}
        if(cmd.equals("reconstruct")){require(peer.equals("recovery-executor"),"RECOVERY_EXECUTOR_REQUIRED");var snapshot=unpack(r.get("snapshot"));verify(d,snapshot,r.get("snapshot-signature"));var now=current(tenant);require(now.get("revision").equals(snapshot.get("revision"))&&now.get("ledger").equals(snapshot.get("ledger")),"AUTHORITY_CHANGED_DURING_RECONCILIATION");var ledger=ReconciliationPolicy.ledger(snapshot);try(var c=db(cell)){c.setAutoCommit(false);var g=gate(c,true);require(g.get("attempt").equals(r.get("attempt"))&&Set.of("VALIDATING","RECONCILING").contains(g.get("state")),"RECONCILIATION_STATE");var original=data(c);require(ReconciliationPolicy.digest(original).equals(r.get("validated-digest")),"DATA_CHANGED_AFTER_VALIDATION");var old=unpack(original.get("operations"));var accepted=new TreeMap<String,String>();for(var op:ledger)accepted.put(op.get("id"),packed(op));for(var e:old.entrySet())require(accepted.containsKey(e.getKey())&&accepted.get(e.getKey()).equals(e.getValue()),"RESTORED_OPERATION_DIGEST_CONFLICT");int reconstructed=0;for(var op:ledger)if(!old.containsKey(op.get("id"))){insertOperation(c,op);audit(c,tenant,r.get("attempt"),"RECONSTRUCTION",op.get("id"),"COMMITTED",op.get("digest"));reconstructed++;}if(!ledger.isEmpty()){var last=ledger.getLast();try(var p=c.prepareStatement("UPDATE lab_data.markers SET version=?,value=? WHERE marker_id='marker'")){p.setLong(1,ledger.size());p.setString(2,last.get("value"));p.executeUpdate();}}
            String digest=ReconciliationPolicy.digest(data(c));try(var p=c.prepareStatement("UPDATE recovery.gate SET state='RECONCILING',placement_epoch=?,credential_epoch=?,fence_generation=?,authority_version=?,checkpoint=?,data_digest=?,acknowledged=false")){p.setLong(1,Long.parseLong(now.get("placement")));p.setLong(2,Long.parseLong(now.get("credential")));p.setLong(3,Long.parseLong(now.get("fence")));p.setLong(4,Long.parseLong(now.get("revision")));p.setLong(5,ledger.size());p.setString(6,digest);p.executeUpdate();}c.commit();return map("code","OK","state","RECONCILING","data-digest",digest,"reconstruction-effects",""+reconstructed,"original-operations-executed","0");}}
        if(cmd.equals("activate")){require(peer.equals("recovery-executor"),"RECOVERY_EXECUTOR_REQUIRED");var ack=unpack(r.get("body"));verify(d,ack,r.get("signature"));var now=current(tenant);try(var c=db(cell)){c.setAutoCommit(false);var g=gate(c,true);require(g.get("state").equals("RECONCILING")&&g.get("attempt").equals(ack.get("attempt"))&&g.get("incarnation").equals(ack.get("incarnation"))&&ack.get("acknowledged").equals("true"),"ACTIVATION_ACK_BINDING");for(String f:List.of("tenant","cell","placement","credential","fence","revision"))require(g.get(f).equals(now.get(f))&&ack.get(f).equals(now.get(f)),"ACTIVATION_AUTHORITY_CHANGED");require(System.currentTimeMillis()<Long.parseLong(ack.get("expires")),"ACTIVATION_GRANT_EXPIRED");String digest=ReconciliationPolicy.digest(data(c));require(digest.equals(g.get("data-digest"))&&digest.equals(ack.get("data-digest")),"DATA_CHANGED_BEFORE_ACTIVATION");try(var s=c.createStatement()){s.executeUpdate("UPDATE recovery.gate SET state='ACTIVE',acknowledged=true");}audit(c,tenant,g.get("attempt"),"STATE","","ACTIVE",digest);c.commit();return map("code","OK","state","ACTIVE");}}
        if(cmd.equals("read")){require(admin||peer.equals("client-"+cell+"-current")||peer.equals("client-"+cell+"-old"),"WORKLOAD_TENANT_IDENTITY");var now=current(tenant);require(!peer.endsWith("-old")||now.get("credential").equals("1"),"CREDENTIAL_REVOKED");try(var c=db(cell)){active(gate(c,false),now);var result=data(c);require(result.get("operations").equals(byId(now)),"COMPLETION_STATE_NOT_CURRENT");result.put("code","OK");return result;}}
        if(cmd.equals("operate")&&admin){var now=current(tenant);try(var c=db(cell)){c.setAutoCommit(false);var g=gate(c,true);if(node.equals("restored-owner"))active(g,now);else require(!now.get("suspended").equals("true"),"TENANT_SUSPENDED");require(r.getOrDefault("fence",now.get("fence")).equals(now.get("fence")),"STALE_OPERATION_FENCE");var before=data(c);String id=r.get("id"),value=r.get("value");require(id.matches("op-[0-9]{1,8}")&&value.matches("[A-Z0-9_-]{1,32}"),"OPERATION_PARAMETER");var old=unpack(before.get("operations"));if(old.containsKey(id)){var op=unpack(old.get(id));require(op.get("value").equals(value),"COMMAND_ID_CONFLICT");c.rollback();return map("code","OK","duplicate","true","operation",old.get(id));}long seq=Long.parseLong(before.get("sequence"))+1;var op=map("tenant",tenant,"id",id,"sequence",""+seq,"value",value,"state","COMMITTED","digest",hash((tenant+"|"+id+"|"+seq+"|"+value).getBytes(StandardCharsets.UTF_8)));insertOperation(c,op);try(var p=c.prepareStatement("UPDATE lab_data.markers SET version=?,value=? WHERE marker_id='marker'")){p.setLong(1,seq);p.setString(2,value);p.executeUpdate();}audit(c,tenant,"workload",node.equals("source-owner")?"HISTORICAL":"NEW",id,"COMMITTED",op.get("digest"));c.commit();var recorded=call(d,"recovery-authority",8443,map("command","record","body",packed(op)));require("OK".equals(recorded.get("code")),"COMPLETION_ACK_UNKNOWN");return map("code","OK","duplicate","false","operation",packed(op));}}
        throw new Denied("WORKLOAD_COMMAND");
    }
    private String byId(Map<String,String> snapshot)throws Exception{var m=new TreeMap<String,String>();for(var op:ReconciliationPolicy.ledger(snapshot))m.put(op.get("id"),packed(op));return packed(m);}
    private void insertOperation(Connection c,Map<String,String> op)throws Exception{try(var p=c.prepareStatement("INSERT INTO lab_data.operations VALUES (?,?,?,?,?)")){p.setString(1,op.get("tenant"));p.setString(2,op.get("id"));p.setString(3,op.get("digest"));p.setLong(4,Long.parseLong(op.get("sequence")));p.setString(5,packed(op));p.executeUpdate();}try(var p=c.prepareStatement("INSERT INTO lab_data.outbox VALUES (?,?,?)")){p.setString(1,op.get("tenant"));p.setString(2,op.get("id"));p.setString(3,packed(op));p.executeUpdate();}}
    public static void main(String[] args)throws Exception{var w=new LabRecoveryWorkload(Path.of(args[0]),args[2]);serve(w.d,args[1],w::handle);}
}
